module tb_TopModule;

    reg  [255:0] in;
    reg  [7:0]   sel;
    wire         out;

    TopModule dut (
        .in(in),
        .sel(sel),
        .out(out)
    );

    initial begin
        // Test random patterns or specific selections
        in = 256'h123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0;

        // Check some specific bits
        for (integer i = 0; i < 256; i = i + 1) begin
            sel = i[7:0];
            #1;
            if (out !== in[i]) begin
                $display("SELFTEST FAIL: sel=%d, expected=%b, got=%b", i, in[i], out);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
